<?php
namespace App\Http\Controllers;
use App\Models\{Product,StorageRow,RowInventory,InventoryMovement};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class InventoryController extends Controller {
 public function index(){return view('inventory.index',['products'=>Product::where('is_active',true)->orderBy('name')->get(),'rows'=>StorageRow::with('rack.aisle.warehouse')->where('is_active',true)->whereHas('rack',fn($q)=>$q->where('is_active',true)->whereHas('aisle',fn($a)=>$a->where('is_active',true)->whereHas('warehouse',fn($w)=>$w->where('is_active',true))))->orderBy('code')->get(),'stocks'=>RowInventory::with(['product','row.rack.aisle.warehouse'])->latest()->paginate(30),'movements'=>InventoryMovement::with(['product','fromRow','toRow','user'])->latest()->take(15)->get()]);}
 public function assign(Request $r){$d=$r->validate(['product_id'=>['required',Rule::exists('products','id')->where('is_active',true)],'storage_row_id'=>['required',Rule::exists('storage_rows','id')->where('is_active',true)],'quantity'=>'required|numeric|min:0.001','note'=>'nullable|max:1000']);DB::transaction(function()use($d,$r){$stock=RowInventory::firstOrCreate(['product_id'=>$d['product_id'],'storage_row_id'=>$d['storage_row_id']],['quantity'=>0]);$stock->increment('quantity',$d['quantity']);InventoryMovement::create(['product_id'=>$d['product_id'],'to_row_id'=>$d['storage_row_id'],'quantity'=>$d['quantity'],'user_id'=>$r->user()->id,'type'=>'in','note'=>$d['note']??null]);});return back()->with('success','موجودی به ردیف تخصیص داده شد.');}
 public function move(Request $r){$d=$r->validate(['product_id'=>['required',Rule::exists('products','id')->where('is_active',true)],'from_row_id'=>['required',Rule::exists('storage_rows','id')->where('is_active',true),'different:to_row_id'],'to_row_id'=>['required',Rule::exists('storage_rows','id')->where('is_active',true)],'quantity'=>'required|numeric|min:0.001','note'=>'nullable|max:1000']);DB::transaction(function()use($d,$r){$source=RowInventory::where('product_id',$d['product_id'])->where('storage_row_id',$d['from_row_id'])->lockForUpdate()->first();if(!$source||(float)$source->quantity<(float)$d['quantity'])throw \Illuminate\Validation\ValidationException::withMessages(['quantity'=>'موجودی ردیف مبدأ کافی نیست.']);$source->decrement('quantity',$d['quantity']);$target=RowInventory::firstOrCreate(['product_id'=>$d['product_id'],'storage_row_id'=>$d['to_row_id']],['quantity'=>0]);$target->increment('quantity',$d['quantity']);InventoryMovement::create(['product_id'=>$d['product_id'],'from_row_id'=>$d['from_row_id'],'to_row_id'=>$d['to_row_id'],'quantity'=>$d['quantity'],'user_id'=>$r->user()->id,'type'=>'move','note'=>$d['note']??null]);});return back()->with('success','جابه‌جایی کالا با موفقیت ثبت شد.');}
 public function remove(Request $r){$d=$r->validate(['product_id'=>['required',Rule::exists('products','id')->where('is_active',true)],'storage_row_id'=>['required',Rule::exists('storage_rows','id')->where('is_active',true)],'quantity'=>'required|numeric|min:0.001','note'=>'nullable|max:1000']);DB::transaction(function()use($d,$r){$s=RowInventory::where('product_id',$d['product_id'])->where('storage_row_id',$d['storage_row_id'])->lockForUpdate()->first();if(!$s||(float)$s->quantity<(float)$d['quantity'])throw \Illuminate\Validation\ValidationException::withMessages(['quantity'=>'موجودی کافی نیست.']);$s->decrement('quantity',$d['quantity']);InventoryMovement::create(['product_id'=>$d['product_id'],'from_row_id'=>$d['storage_row_id'],'quantity'=>$d['quantity'],'user_id'=>$r->user()->id,'type'=>'out','note'=>$d['note']??null]);});return back()->with('success','خروج کالا ثبت شد.');}
}
